mapper.select:
SELECT
IFNULL(SUM(actual_quantity), 0) AS actual_quantity,
IFNULL(SUM(actual_mete), 0) AS actual_mete,
IFNULL(SUM(actual_total_area), 0) AS actual_total_area
FROM project_install_report
WHERE bool_delete_enum = 0
AND audit_status = 2

    AND supplier_id = #{supplierId}


    AND project_id = #{projectId}


    AND monomer_id = #{monomerId}


    AND area_id = #{areaId}


    AND product_type = #{productType}


    AND category = #{category}

SELECT pir.project_id, cp.id as 'project.id', cp.name as 'project.name', cp.short_name AS 'project.short_name', cp.serial_number as 'project.serial_number',
DATE_FORMAT(pir.create_time,'%Y/%m/%d') as report_date,
pir.supplier_id, (SELECT `name` FROM scm_supplier WHERE id = pir.supplier_id ) as supplier_name, pir.project_type, pir.product_type, pir.category, SUM( pir.report_quantity ) AS report_quantity, SUM( pir.report_mete ) AS report_mete, SUM(pir.report_total_area) as report_total_area, IFNULL( SUM( pir.actual_quantity ), 0 ) AS actual_quantity, IFNULL( SUM( pir.actual_mete ), 0 ) AS actual_mete , IFNULL( SUM( pir.actual_total_area ), 0 ) AS actual_total_area FROM project_install_report AS pir LEFT JOIN contract_project AS cp ON cp.id = pir.project_id AND cp.bool_delete_enum = 0 WHERE pir.bool_delete_enum = 0
AND pir.project_id = #{projectId}
AND pir.product_type = #{productType}
AND DATE_FORMAT(pir.create_time,'%Y-%m') = #{yearMonth}
GROUP BY pir.project_id, pir.project_type, pir.supplier_id, pir.product_type, pir.category
, DATE_FORMAT(pir.create_time,'%Y/%m/%d') order by report_date desc

select IFNULL(sum(report_quantity), 0)
from project_install_report
where bool_delete_enum = 0
  and audit_status = 1
  and project_type & #{projectType}
  and product_type = #{productType}
  and product_id = #{productId}

SELECT temp.*, p.id AS 'project.id', p.name AS 'project.name', p.short_name AS 'project.shortName', p.serial_number AS 'project.serialNumber', m.id AS 'monomer.id', m.`name` AS 'monomer.name', a.id AS 'area.id', a.`name` as 'area.name' FROM (SELECT pir.product_type, pir.product_id, pir.project_id, pir.monomer_id, pir.area_id, SUM( pir.actual_quantity ) AS actual_quantity, SUM( pir.actual_mete ) AS actual_mete, SUM( pir.actual_total_area ) / 1000000 AS actual_total_area FROM project_install_report AS pir WHERE pir.bool_delete_enum = 0 AND pir.audit_status = 2
AND pir.project_id = #{projectId}
AND pir.monomer_id = #{monomerId}
AND pir.area_id = #{areaId}
AND pir.supplier_id = #{supplierId}
GROUP BY pir.product_type, pir.product_id, pir.project_id, pir.monomer_id, pir.area_id ORDER BY pir.product_id ) AS temp LEFT JOIN contract_project AS p ON temp.project_id = p.id AND p.bool_delete_enum = 0 LEFT JOIN plan_monomer AS m ON temp.monomer_id = m.id AND m.bool_delete_enum = 0 LEFT JOIN plan_area AS a ON temp.area_id = a.id AND a.bool_delete_enum = 0

SELECT *
FROM project_install_report
WHERE bool_delete_enum = 0

    AND project_id = #{projectId}


    AND supplier_id = #{supplierId}


    AND product_type = #{productType}


    AND category = #{category}


    AND audit_status = #{auditStatus}


    AND DATE_FORMAT( create_time, '%Y-%m' ) = #{yearMonth}


    AND DATE_FORMAT( create_time, '%Y/%m/%d' ) = #{yearMonthDay}


    AND date(create_time) >= #{startDate}


    AND date(create_time) <= #{endDate}


    AND report_method = #{reportMethod}

ORDER BY audit_status ASC, create_time DESC

        SELECT
        
            DATE_FORMAT(create_time, '%m') date,
        
        
            DATE_FORMAT(create_time, '%d') date,
        
        project_type,
        product_type,
        SUM(actual_quantity) as actual_quantity,
        
            case product_type
            when 4 then IFNULL(SUM(actual_mete),0)/1000
            else IFNULL(SUM(actual_mete),0) end as actual_mete,
            IFNULL(SUM(actual_total_area), 0)/1000000 as actual_total_area
        
        FROM `project_install_report`
        WHERE bool_delete_enum = 0
        AND audit_status = 2
        AND project_type & #{projectType}
        AND product_type = #{productType}
        
            AND DATE_FORMAT(create_time, '%Y') = #{year}
        

        
            AND project_id = #{projectId}
        
        
            AND supplier_id = #{supplierId}
        
        
            GROUP BY project_type, product_type, DATE_FORMAT(create_time, '%m')
        
        
            AND DATE_FORMAT(create_time, '%m') = #{month}
            GROUP BY project_type, product_type, DATE_FORMAT(create_time, '%d')

SELECT project_id, monomer_id as 'monomer.id', (select name from plan_monomer where id = monomer_id and bool_delete_enum = 0) as 'monomer.name', area_id as 'area.id', (select name from plan_area where id = area_id and bool_delete_enum = 0) as 'area.name', project_type, product_type, category, product_id, supplier_id, (SELECT `name` FROM scm_supplier WHERE bool_delete_enum = 0 AND id = supplier_id) AS supplier_name, serial_number, `name`, specification, (case product_type when 2 then '件' when 4 then '张' else measure_unit end ) as measure_unit, (case product_type when 2 then 'kg' when 4 then 'm' else accounting_unit end ) as accounting_unit,
(case product_type when 4 then IFNULL(SUM(actual_mete),0)/1000 else IFNULL(SUM(actual_mete),0) end ) as actual_mete, IFNULL(SUM(actual_quantity),0) AS actual_quantity, IFNULL(SUM(actual_total_area),0)/1000000 AS actual_total_area FROM project_install_report WHERE bool_delete_enum = 0 AND audit_status = 2
AND product_type = #{productType}
AND project_id = #{projectId}
AND monomer_id = #{monomerId}
AND area_id = #{areaId}
AND supplier_name LIKE concat('%',#{supplierName},'%')
AND serial_number LIKE concat('%',#{serialNumber},'%')
AND name LIKE concat('%',#{name},'%')
AND DATE_FORMAT(create_time,'%Y-%m-%d') >= #{startDate}
AND DATE_FORMAT(create_time,'%Y-%m-%d') <= #{endDate}
GROUP BY project_id, monomer_id, area_id, project_type, product_type, category, product_id, supplier_id, serial_number, `name`, specification, measure_unit, accounting_unit

SELECT pir.project_id, cp.id as 'project.id', cp.name as 'project.name', cp.short_name AS 'project.short_name', cp.serial_number as 'project.serial_number', pir.supplier_id, (SELECT `name` FROM scm_supplier WHERE id = pir.supplier_id) AS supplier_name, pir.project_type, pir.product_type, pir.category, SUM( pir.report_quantity ) AS report_quantity, SUM( pir.report_mete ) AS report_mete, SUM(pir.report_total_area) as report_total_area, IFNULL( SUM( pir.actual_quantity ), 0 ) AS actual_quantity, IFNULL( SUM( pir.actual_mete ), 0 ) AS actual_mete , IFNULL( SUM( pir.actual_total_area ), 0 ) AS actual_total_area
FROM project_install_report AS pir LEFT JOIN contract_project as cp on cp.id = pir.project_id AND cp.bool_delete_enum = 0 WHERE pir.bool_delete_enum = 0 AND pir.audit_status = 1
AND pir.project_id = #{projectId}
AND pir.product_type = #{productType}
GROUP BY pir.project_id, pir.supplier_id, pir.project_type, pir.product_type, pir.category

SELECT COUNT(*)
FROM project_install_report
WHERE bool_delete_enum = 0
AND audit_status = 1
AND supplier_id = #{supplierId}
AND product_type = #{productType}
AND project_id = #{projectId}

    AND DATE_FORMAT(create_time,'%Y/%m/%d') = #{reportDate}


    AND category = #{category}


    AND category is null
